/* A self-contained design review. All changes are in-memory and discarded on reload. */
'use strict';
const root=document.getElementById('app');
const state={screen:location.hash.slice(1)||'landing',studyFilter:'All studies',query:'',audit:'dashboard',processing:'processing',appraisal:0,verifiedFields:new Set(),corrections:{},selectedObject:'pendants',removed:new Set(),overlays:true,assetTab:'Overview',setting:'Cost sources',metrics:false,roomsFilter:'All photos',photoReviewed:false,group:{},uploads:[],propertyName:'Harbor House',propertyAddress:'',clientName:'Harbor Property Partners',approved:new Set(),selectedAsset:0};
const icons={sort:'M4 6h16 M7 12h10 M10 18h4',folder:'M3 7V4h6l2 3h10v13H3z',home:'M3 10l9-7 9 7 M5 9v12h5v-7h4v7h5V9',panelOpen:'M3 4h18v16H3z M9 4v16 M13 9l3 3-3 3',panelClose:'M3 4h18v16H3z M9 4v16 M17 9l-3 3 3 3',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',image:'M3 3h18v18H3z M3 17l5-5 4 4 3-3 6 6 M8 8h.01',search:'M21 21l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',settings:'M9.5 2h5l.6 3 2 .9 2.7-1 2.5 4.2-2.2 2v2.2l2.2 2-2.5 4.2-2.7-1-2 .9-.6 3h-5l-.6-3-2-.9-2.7 1-2.5-4.2 2.2-2v-2.2l-2.2-2L4.3 5.9l2.7 1 2-.9.5-3z M15.5 12a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M17 4a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M5 12h14 M13 6l6 6-6 6',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',download:'M12 3v12 M7 10l5 5 5-5 M3 17v4h18v-4',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',shield:'M12 2L3 6v6c0 6 9 10 9 10s9-4 9-10V6z M8 12l3 3 5-6',mail:'M3 5h18v14H3z M3 5l9 8 9-8',back:'M19 12H5 M11 6l-6 6 6 6',x:'M6 6l12 12 M18 6L6 18',building:'M4 22V4h16v18 M1 22h22 M8 8h2 M14 8h2 M8 12h2 M14 12h2 M8 16h2 M14 16h2',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',layers:'M12 2L2 7l10 5 10-5z M2 12l10 5 10-5 M2 17l10 5 10-5'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo=(destination='landing')=>`<a class="logo" href="#${destination}" aria-label="Basis home"><img class="logo-full" src="assets/basis-logo.png" alt="Basis"><img class="logo-mark" src="assets/basis-mark.png" alt="Basis"></a>`;
const goButton=(label,screen,primary=false,ico='')=>`<a class="button ${primary?'primary':''}" href="#${screen}">${ico?icon(ico):''}${label}</a>`;
const btn=(label,action,value='',style='',ico='')=>`<button class="button ${style}" data-action="${action}" data-value="${esc(value)}">${ico?icon(ico):''}${label}</button>`;
const statusBadge=(status)=>{let titles={waiting_review:'Needs review',completed:'Completed',processing:'Processing',draft:'Draft',stalled:'Needs attention',archived:'Archived',cancelled:'Cancelled'};return `<span class="badge ${status==='waiting_review'||status==='stalled'?'review':status==='completed'?'complete':status==='processing'?'processing':''}"><span class="dot"></span>${titles[status]||status}</span>`};
const heading=(title,description,actions='')=>`<div class="heading"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="row wrap">${actions}</div>`:''}</div>`;
function reviewbar(){return `<div class="reviewbar"><div class="row"><strong>Basis</strong><span class="label">Design review</span><select id="screen-select" aria-label="Preview screen">${REVIEW.screens.map(([id,name])=>`<option value="${id}" ${state.screen===id?'selected':''}>${name}</option>`).join('')}</select></div><div class="row"><span class="prototype-label">Illustrative data · no live actions</span><a class="audit-link" href="#audit">Existing pages</a><a href="#roadmap">Page gaps</a></div></div>`}
function shell(content){const studyScreens=['appraisal','rooms','viewer','assets','asset-detail','verification','complete','processing'];let inStudy=studyScreens.includes(state.screen);return `<div class="workspace"><aside class="sidebar">${logo()}<div class="workspace-name"><span class="avatar">HE</span><span>Enterprise workspace</span>${icon('down',12)}</div><nav class="nav" aria-label="Workspace"><a href="#dashboard" class="${state.screen==='dashboard'?'active':''}" title="Studies">${icon('grid')}<span class="nav-text">Studies</span></a><a href="#upload" class="${state.screen==='upload'?'active':''}" title="New study">${icon('plus')}<span class="nav-text">New study</span></a><a href="#activity" class="${state.screen==='activity'?'active':''}" title="Activity">${icon('clock')}<span class="nav-text">Study activity</span></a><a href="#team" class="${state.screen==='team'?'active':''}" title="Team & access">${icon('users')}<span class="nav-text">Team & access</span></a></nav><div class="side-bottom"><nav class="nav"><a href="#settings" class="${state.screen==='settings'?'active':''}" title="Settings">${icon('settings')}<span class="nav-text">Settings</span></a><a href="#roadmap" title="Design notes">${icon('help')}<span class="nav-text">Design notes</span></a></nav><div class="row account" style="padding:18px 7px 0"><span class="avatar">AM</span><div><strong class="small">Alex Morgan</strong><p>Engineer</p></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><a href="#dashboard">Studies</a>${inStudy?`${icon('chevron',12)}<span class="strong">Harbor House</span>`:`${icon('chevron',12)}<span class="strong">${esc(REVIEW.screens.find(x=>x[0]===state.screen)?.[1]||'Workspace')}</span>`}</div><div class="row right-meta">${inStudy?'<span>Revision 1</span><span class="badge complete">Sample study</span>':'<span>Sample workspace</span><span class="avatar">AM</span>'}</div></header><div class="content">${content}</div></main></div>`}
function steps(active){const labels=['Upload','Appraisal','Rooms','Assets','Schedule'];return `<nav class="steps" aria-label="Study progress">${labels.map((l,i)=>`<a href="#${['upload','appraisal','rooms','assets','complete'][i]}" class="step ${i<active?'done':i===active?'active':''}"><span>${i<active?'✓':i+1}</span>${l}</a>`).join('')}</nav>`}
function miniProduct(){return `<div class="hero-preview"><div class="mini-window"><div class="mini-topbar"><span><strong>Harbor House</strong> / Photo review</span><span class="badge complete">Engineer review</span></div><div class="mini-photo"><img src="assets/kitchen.webp" alt="Property kitchen with pendant lights, cabinetry, and a stone island"><svg class="mask-overlay" viewBox="0 0 1000 667" aria-hidden="true"><path class="mask-shape selected" d="${REVIEW.objects[0].path}"/><path class="mask-shape" d="${REVIEW.objects[1].path}"/></svg><div class="mini-insight"><span><b>Pendant lights</b><br>3 detected instances</span><span class="badge complete">Keep in inventory</span></div></div><div class="mini-foot"><div><strong>Review the photo</strong>See each component</div><div><strong>Check the evidence</strong>Keep sources in view</div><div><strong>Make the decision</strong>Engineer approval</div></div></div></div>`}
function landing(){return `<main class="marketing"><nav class="marketing-nav" aria-label="Public navigation">${logo()}<div class="links"><a href="#landing" data-scroll="features">Features</a><a href="#landing" data-scroll="workflow">How it works</a><a href="#landing" data-scroll="pricing">Pricing</a><a href="#landing" data-scroll="faqs">FAQs</a></div><div class="row">${goButton('Sign in','login')}${goButton('Explore the workspace','dashboard',true)}</div></nav><section class="hero"><div><h1>Cost segregation,<br>accelerated.</h1><p>A focused workspace for cost segregation engineers. Bring appraisal data, property photos, and asset review into one connected study.</p><div class="row wrap">${btn('Book a demo','demo','','primary')}${goButton('Explore sample workspace','dashboard')}</div><div class="hero-note">From source documents to an engineer-reviewed schedule.</div></div>${miniProduct()}</section><div class="marketing-strip"><span>${icon('file')} Appraisal-led</span><span>${icon('image')} Photo by photo</span><span>${icon('layers')} Component by component</span><span>${icon('check')} Reviewed by an engineer</span></div><section class="marketing-section" id="features"><h2>Support for the work<br>behind every study.</h2><div class="enterprise-grid" style="margin-top:30px"><article class="panel panel-body"><h3>Document integration</h3><p style="margin-top:10px">Bring appraisal details and property photos together, with the original sources close by.</p></article><article class="panel panel-body"><h3>A focused review workflow</h3><p style="margin-top:10px">Move through appraisal, rooms, and assets with a clear place for each engineering decision.</p></article><article class="panel panel-body"><h3>Photo organization</h3><p style="margin-top:10px">Keep useful room groups and inspect components within the context of each photo.</p></article><article class="panel panel-body"><h3>Classification review</h3><p style="margin-top:10px">Give quantities, cost sources, and supporting documentation a consistent place in the workspace.</p></article></div></section><section class="marketing-section" id="workflow"><h2>Less switching between files.<br>More focus on the study.</h2><div class="workflow-columns"><article><span class="check">1</span><h3>Start with the source.</h3><p>Collect the appraisal and property photos. Keep the original documents close throughout the review.</p></article><article><span class="check">2</span><h3>Review what matters.</h3><p>Check extracted fields, organize rooms, and inspect detected components before moving forward.</p></article><article><span class="check">3</span><h3>Build the asset schedule.</h3><p>Bring quantities, costs, and classification evidence together for the engineer’s final decision.</p></article></div></section><section class="marketing-section marketing-feature" id="evidence"><div>${miniProduct()}</div><div><h2>Your judgment.<br>With the evidence in view.</h2><p>Select a component, inspect its context, and review the information behind it. The workspace makes the next decision clear while keeping the source one click away.</p>${goButton('Open the photo review concept','viewer')}</div></section><section class="marketing-section" id="pricing"><div class="row between wrap"><h2>Pricing & offers</h2><span class="badge review">Original tiers · pending confirmation</span></div><p class="small" style="margin-top:16px">The original page’s plan structure is retained here for layout review. These are historical draft prices, not a current offer.</p><div class="workflow-columns pricing-columns">${[['Free','$0','per month','2 projects per month · original draft'],['Team','$750','per month','50 projects per month · original draft'],['Enterprise','Custom','Original draft: $2,000–$5,000 / month','Unlimited projects · original draft']].map(x=>`<article class="panel panel-body"><h3>${x[0]}</h3><div style="font-size:32px;margin:16px 0 4px;letter-spacing:-1px">${x[1]}</div><p class="small">${x[2]}</p><p style="margin:22px 0 16px;font-size:12px">${x[3]}</p><ul class="pricing-benefits">${(x[0]==='Free'?['Photo & document analysis','Depreciation table export','Standard report template']:x[0]==='Team'?['Team workspace & shared review','Benchmarking & quality control','PDF & Excel report export','Email & chat support']:['API access & integrations','Custom model fine-tuning','Dedicated onboarding','SLA & compliance support','Multi-office analytics']).map(f=>`<li>${icon('check',13)}${f}</li>`).join('')}</ul>${btn(x[0]==='Enterprise'?'Contact the team':'Start for free','demo','','small')}</article>`).join('')}</div></section><section class="marketing-section" id="faqs"><h2>Common questions</h2><div style="margin-top:25px">${[['Who is Basis designed for?','Cost segregation engineers reviewing property documents, room inventories, and asset classifications.'],['What does the engineer review?','The workflow is organized around three review gates: appraisal details, rooms and photos, and asset information.'],['Can I keep photos organized by room?','Yes. Room groups remain central to the design, with controls to move photos and inspect their components.']].map(x=>`<details style="padding:20px 0;border-bottom:1px solid var(--line)"><summary style="cursor:pointer;font-weight:500">${x[0]}</summary><p style="font-size:13px;margin-top:13px">${x[1]}</p></details>`).join('')}</div></section><section class="marketing-section"><div class="panel panel-body row between wrap"><div><h2 style="font-size:25px">See how the study comes together.</h2><p style="margin-top:10px;font-size:13px">Explore the sample workspace now. A recorded product walkthrough can live here later.</p></div>${goButton('Explore sample workspace','dashboard',true)}</div></section><footer class="marketing-footer"><div class="marketing-footer-inner"><div>${logo()}<p>A clearer workspace for cost segregation.</p><p>Local design concept. Product preview uses illustrative data and hand-drawn overlays.</p></div><div class="row wrap"><a href="#login">Sign in</a><a href="#audit">Design review</a><a href="#roadmap">Planned enterprise pages</a></div></div></footer></main>`}
function login(){return `<main class="login"><section class="login-story">${logo()}<h2>A clear view of every study.</h2><p>Your documents, observations, and engineering decisions. Together in one workspace.</p>${miniProduct()}<p class="small" style="margin-top:auto;padding-top:30px">Built around the engineer’s review.</p></section><section class="login-form"><div class="login-form-inner"><h1>Welcome to Basis</h1><p>Sign in to your engineering workspace.</p>${btn('Continue with Google','sample-login','','','shield')}<p class="small">Use the Google account associated with your workspace.</p><div style="border-top:1px solid var(--line);margin-top:35px;padding-top:23px"><p class="small">Need access to a workspace?</p>${btn('View access request concept','access','','quiet small','help')}</div><a class="screen-link" href="#landing">Back to Basis</a><p class="footnote">Sign-in preview only. The production Google authentication flow is unchanged.</p></div></section></main>`}
function dashboard(){let filtered=REVIEW.studies.filter(s=>(state.studyFilter==='All studies'||(state.studyFilter==='Needs review'&&['waiting_review','stalled'].includes(s.status))||(state.studyFilter==='Processing'&&s.status==='processing')||(state.studyFilter==='Completed'&&s.status==='completed'))&&s.property_name.toLowerCase().includes(state.query.toLowerCase()));return `${heading('Studies','A clear view of what’s ready, what’s running, and what needs you.',goButton('New study','upload',true,'plus'))}<div class="metrics"><div class="metric"><p>Active studies</p><div class="value num">5</div><span class="small">Across the sample workspace</span></div><div class="metric"><p>Ready for review</p><div class="value num">2</div><a class="screen-link" href="#appraisal">Open next review</a></div><div class="metric"><p>Processing</p><div class="value num">1</div><span class="small">Willow Street Apartments</span></div><div class="metric"><p>Needs attention</p><div class="value num">1</div><a class="screen-link" href="#processing" data-processing="stalled">Review flagged photos</a></div></div><div class="attention"><div class="row">${icon('clock',19)}<div><span class="strong">Harbor House is ready for appraisal review.</span><p>Review extracted fields before the study moves to rooms.</p></div></div>${goButton('Review study','appraisal')}</div><div class="tabs" aria-label="Filter studies">${['All studies','Needs review','Processing','Completed'].map((x,i)=>`<button data-action="filter" data-value="${x}" class="${state.studyFilter===x?'active':''}">${x}<span class="badge">${[6,3,1,1][i]}</span></button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="study-search" aria-label="Search studies" placeholder="Search studies" value="${esc(state.query)}"></label>${btn(state.metrics?'Hide financial summary':'Financial summary','metrics','','quiet small')}</div><div id="study-table">${studyTable(filtered)}</div>${state.metrics?`<div class="panel panel-body" style="margin-top:20px"><h3>Illustrative financial summary</h3><div class="form-grid" style="margin-top:14px"><p>Estimated fee revenue<br><strong class="strong">$4,500</strong></p><p>Modeled savings<br><strong class="strong">$30,000</strong></p></div><p class="footnote">Retains the current dashboard’s metric concept. Validate calculation basis and permissions before wiring.</p></div>`:''}<p class="footnote">All studies, values, and activity on this preview are illustrative. Row actions open visual concepts.</p>`}
function studyTable(rows){return `<div class="panel tablewrap"><table><thead><tr><th>Property</th><th>Status</th><th>Current stage</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><div class="property"><img src="assets/${s.image}" alt=""><div><b>${s.property_name}</b><small>${s.detail}</small></div></div></td><td>${statusBadge(s.status)}</td><td class="muted">${{appraisal_review:'Appraisal review',assets_review:'Assets review',extracting:'Extracting & analyzing photos',completed:'Schedule ready',uploading:'Upload documents'}[s.current_stage]}</td><td class="muted">${s.updated}</td><td class="text-right"><a class="button small" href="#${s.next}" ${s.status==='stalled'?'data-processing="stalled"':''}>${s.status==='completed'?'View schedule':'Continue'}${icon('chevron',12)}</a></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-screen"><h3>No matching studies</h3><p>Try a different property name or choose All studies.</p></div></td></tr>'}</tbody></table></div>`}
function upload(){return `${steps(0)}${heading('Start a new study','Add the source documents. You’ll review the results at each stage.')}<div class="two-col"><div class="stack"><section class="panel"><div class="panel-head"><h2>Study details</h2></div><div class="panel-body study-identity-fields"><div class="field"><label for="property-name">Property name</label><input id="property-name" value="${esc(state.propertyName)}" placeholder="e.g. Harbor House"></div><div class="field"><label for="client-name">Client name</label><input id="client-name" value="${esc(state.clientName||'')}" placeholder="e.g. Harbor Property Partners" autocomplete="off"></div><div class="field address-field"><label for="property-address">Property address</label><div class="address-input-wrap">${icon('search',18)}<input id="property-address" value="${esc(state.propertyAddress||'')}" placeholder="Start typing a street address…" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="address-suggestions" aria-describedby="address-help"></div><p id="address-help">Choose a suggested address or enter one manually.</p></div></div></section><section class="panel"><div class="panel-head"><h2>Study files</h2><span class="small">${state.uploadItems.length} selected</span></div><div class="panel-body">${uploadWorkspaceBody()}</div></section></div><aside class="stack" style="align-content:start"><section class="panel panel-body"><h3>What happens next</h3><div class="timeline"><div><span class="check">1</span><div><strong class="small">Appraisal review</strong><p>Check extracted property details against the source.</p></div></div><div><span class="check">2</span><div><strong class="small">Rooms review</strong><p>Organize photos and review the component inventory.</p></div></div><div><span class="check">3</span><div><strong class="small">Assets review</strong><p>Review classification, quantities, and costs.</p></div></div></div></section><div class="note"><h3>Your review stays central.</h3><p>The study pauses for an engineer’s decision at each review gate.</p></div></aside></div><div class="actionbar"><p>Design preview. Upload and analysis services are not connected.</p><div class="row">${goButton('Back to studies','dashboard')}${btn('Preview analysis','preview-analysis','','primary','arrow')}</div></div>`}
function processing(){const mode=state.processing,p=REVIEW.workflow.status;const configs={processing:['Analysis in progress','Basis is extracting appraisal fields and reviewing property photos.'],extracting:['Reading the appraisal','Extracting property details. Progress is shown when measurable.'],stalled:['This study needs attention','The processing budget was reached. Review the affected photos and stages.'],disconnected:['Connection interrupted','The study may still be running. Current progress cannot be confirmed.'],unavailable:['Workflow status unavailable','The server could not query the worker. The last confirmed state is shown.'],failed:['Processing stopped','The workflow failed. Review its last completed stage before deciding how to continue.'],cancelled:['Study cancelled','Processing has stopped. Existing documents and review history remain visible.'],archived:['Study archived','This study is shown as read-only.'],draft:['Ready for source documents','Add an appraisal and photos before starting the study.']};let [title,desc]=configs[mode];return `${steps(1)}<div class="statebar"><strong>Preview a workflow state</strong><select id="workflow-state" aria-label="Workflow state">${Object.keys(configs).map(x=>`<option ${mode===x?'selected':''} value="${x}">${x.charAt(0).toUpperCase()+x.slice(1)}</option>`).join('')}</select><span class="muted">Design controls only</span></div>${heading(title,desc,goButton('Back to studies','dashboard'))}${mode==='draft'?`<div class="empty-screen">${icon('upload',34)}<h2>Add your study documents</h2><p>An appraisal and property photos give the study its source material.</p>${goButton('Go to upload','upload',true)}</div>`:mode==='stalled'?`<div class="attention"><div><h3>Budget reached · sample exception</h3><p>3 photos are flagged. Rooms review needs an engineer’s attention.</p></div>${goButton('Inspect flagged photos','viewer')}</div><div class="photo-grid">${[['kitchen',0],['exterior',4],['bedroom',3]].map(([image,index])=>photoCard(image,index,true)).join('')}</div><div class="note" style="margin-top:25px"><h3>Review the flagged material.</h3><p>Check the affected photos and review history before deciding how to continue.</p></div>`:mode==='cancelled'||mode==='archived'?`<section class="panel panel-body"><div class="row between wrap"><div><h2>Harbor House</h2><p style="margin-top:10px">Revision 1 · ${mode==='cancelled'?'Cancelled execution':'Archived study'} · sample state</p></div>${statusBadge(mode)}</div><div class="actionbar"><p>Existing records remain available for inspection.</p>${goButton('View study history','activity')}</div></section>`:`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Study progress</h2>${statusBadge(mode==='processing'||mode==='extracting'?'processing':'stalled')}</div><div class="panel-body"><div class="row between"><h3>${mode==='extracting'?'Extracting property details':'Property photos'}</h3><span class="small num">${mode==='extracting'?'In progress':`${p.completed_photos} of ${p.pending_photos+p.completed_photos} processed`}</span></div>${mode==='extracting'?'<p class="small" style="margin-top:15px">A page-completion count is not available. No estimated percentage is shown.</p>':`<div class="progress" style="margin-top:17px"><span style="width:${100*p.completed_photos/(p.pending_photos+p.completed_photos)}%"></span></div>`}<div class="timeline" style="margin-top:25px"><div><span class="check">✓</span><div><strong class="small">Documents registered</strong><p>Appraisal and property photos are ready.</p></div></div><div><span class="check">${mode==='failed'?'!':'2'}</span><div><strong class="small">Extraction & photo analysis</strong><p>${mode==='processing'?'3 photos processed; 2 remaining.':'Last confirmed stage. Live progress is unavailable in this sample state.'}</p></div></div><div><span class="check">3</span><div><strong class="small">Engineer review</strong><p>The next review opens when processing is ready.</p></div></div></div></div></section><aside class="stack" style="align-content:start"><div class="panel panel-body"><h3>Harbor House</h3><div class="line-item"><span>Revision</span><strong>1</strong></div><div class="line-item"><span>Remaining workflow budget</span><strong class="num">$18.40</strong></div><div class="line-item"><span>Last confirmed update</span><strong>9:42 am · sample</strong></div><p class="footnote">Processing budget is not a customer invoice or study value.</p></div><div class="note"><h3>You can leave this screen.</h3><p>Your study keeps processing. Return to My studies to continue working.</p></div></aside></div><div class="actionbar"><p>${mode==='processing'?'Sample progress; no workflow has been launched.':'Do not show a successful retry until the server confirms it.'}</p><div class="row">${btn('Cancel study','cancel','','danger')}${goButton('Preview next review','appraisal',true)}</div></div>`}`}
function appraisal(){const f=REVIEW.appraisalFields[state.appraisal],count=state.verifiedFields.size;return `${steps(1)}${heading('Review the appraisal','Check the property details against their source before approving this stage.',`<span class="badge review">Appraisal review</span>${goButton('Study history','activity')}`)}<div class="review-split"><section class="panel"><div class="panel-head"><div><h2>Property details</h2><p class="small">${count} of ${REVIEW.appraisalFields.length} reviewed in this sample section</p></div><span class="small muted">Revision 1</span></div>${REVIEW.appraisalFields.map((v,i)=>`<button class="field-row ${state.appraisal===i?'selected':''}" data-action="select-field" data-value="${i}"><span class="field-label">${v.label}</span><strong>${esc(state.corrections[i]||v.value)} ${state.verifiedFields.has(i)?'<span style="color:var(--forest)">✓</span>':''}</strong><span class="page-tag">p. ${v.page}</span></button>`).join('')}<div class="panel-body row between wrap"><p class="small">${f.label}</p><div class="row">${btn('Correct value','correct-field',state.appraisal,'small')}${btn(state.verifiedFields.has(state.appraisal)?'Reviewed':'Mark reviewed','verify-field',state.appraisal,'primary small','check')}</div></div><div class="reviewer-hint">Other appraisal sections remain part of the design: neighborhood, site, improvements, sales comparison, cost approach, photos/sketch, and overall review.</div></section><section class="panel source-panel" style="background:#edf2ed"><div class="panel-head" style="background:white"><div class="row">${icon('file')}<strong class="small">Harbor_House_Appraisal.pdf</strong></div><span class="small muted">Page ${f.page} / 24</span></div><div class="sourcepaper"><h3>Uniform Residential Appraisal Report</h3><div class="rule"></div><div class="paper-fields"><span>Subject property</span><strong>1200 Harbor Boulevard</strong><span>Purpose</span><span>Property valuation</span></div><div class="rule"></div><p>This sample page illustrates the relationship between extracted fields and the source document.</p><p>${f.label}<br><mark>${esc(f.value)}</mark></p><p>The production viewer should display the original PDF page with a location reference supplied by the backend.</p><div class="rule"></div><p style="font-size:10px">Illustrative document treatment. This is not an appraisal excerpt.</p></div><div class="reviewer-hint">Click a field to change its source page. Page references and source text shown here are illustrative.</div></section></div><div class="actionbar"><div><strong class="small">Your decision applies to revision 1.</strong><p>${Object.keys(state.corrections).length?'Corrections require rejection and re-extraction.':'Approval confirms the appraisal stage. Corrections return it for extraction.'}</p></div><div class="row">${btn('Request corrections','request-corrections','appraisal_review')}${btn('Approve appraisal','approve','appraisal_review','primary','check')}</div></div>`}
const photos=[['kitchen','Kitchen / 01','Kitchen'],['kitchen-detail','Kitchen / 02','Kitchen'],['living','Living room / 01','Living room'],['bedroom','Bedroom / 01','Bedroom'],['exterior','Exterior / 01','Exterior']];
function photoCard(image,index,flagged=false){const x=photos[index]||photos[0];let group=state.group[index]||x[2];return `<article class="photo-card"><button class="photo-trigger" data-action="open-photo" data-value="${index}" aria-label="Inspect ${x[1]}"><img class="photo" src="assets/${image}.webp" alt="${x[1]}"></button><div class="photo-meta"><div class="row between"><h3>${x[1]}</h3><span class="badge ${flagged?'review':index<2?'complete':''}">${flagged?'Flagged':index<2?'Reviewed':'To review'}</span></div><div class="row between" style="margin-top:10px"><label class="small muted" for="photo-group-${index}">Room</label><select id="photo-group-${index}" class="photo-group" data-photo="${index}" aria-label="Move ${x[1]} to room">${['Kitchen','Living room','Bedroom','Exterior','Unassigned'].map(g=>`<option ${g===group?'selected':''}>${g}</option>`).join('')}</select></div></div></article>`}
function rooms(){let shown=photos.map((p,i)=>({p,i})).filter(({p,i})=>state.roomsFilter==='All photos'||(state.group[i]||p[2])===state.roomsFilter);return `${steps(2)}${heading('Review rooms & photos','Keep the photo groups. Check the inventory one room at a time.',`${btn('Export rooms','future','Room export is a preview here. Existing application behavior is unchanged.','','download')}${btn('Add room','add-room','','','plus')}`)}<div class="row between wrap" style="margin-bottom:24px"><div class="row"><span class="badge review">Rooms review</span><span class="small muted">2 of 5 visible sample photos reviewed</span></div><p class="small">Select a photo to inspect components and materials.</p></div><div class="tabs">${['All photos','Kitchen','Living room','Bedroom','Exterior','Unassigned'].map(g=>`<button data-action="rooms-filter" data-value="${g}" class="${state.roomsFilter===g?'active':''}">${g}</button>`).join('')}</div><div class="row between photo-heading"><h2>${state.roomsFilter==='All photos'?'Property photos':state.roomsFilter}</h2><small>${shown.length} sample photos</small></div><div class="photo-grid">${shown.map(({p,i})=>photoCard(p[0],i)).join('')}</div>${!shown.length?'<div class="empty-screen"><h2>No photos in this room</h2><p>Use the room menu on any photo to move it here.</p></div>':''}<div class="note" style="margin-top:22px"><h3>Review a room, then its components.</h3><p>Use the room menu to organize a photo. Open it to inspect the components in context.</p></div><div class="actionbar"><p>Review corrections return only the affected photos for analysis.</p><div class="row">${btn('Request corrections','request-corrections','rooms_review')}${btn('Approve rooms','approve','rooms_review','primary','check')}</div></div>`}
function viewer(){return `${steps(2)}${heading('Kitchen / 01','Inspect detected components in context. Select an outline or an item in the list.',goButton('Back to rooms','rooms',false,'back'))}<div class="viewer"><div class="photo-stage"><div class="photo-toolbar"><span>Harbor House / Kitchen / Photo 01</span><div class="row gap6">${btn(state.overlays?'Hide outlines':'Show outlines','toggle-overlay','','small','eye')}<span>Fit</span></div></div><div class="photo-canvas"><img src="assets/kitchen.webp" alt="Kitchen photo with pendant lights, cabinetry, stone countertop and counter stools"><svg class="mask-overlay ${state.overlays?'':'hidden'}" viewBox="0 0 1000 667" aria-label="Illustrative component outlines">${REVIEW.objects.map(o=>`<path role="button" tabindex="0" aria-label="Select ${o.label}" class="mask-shape ${state.selectedObject===o.id?'selected':''}" data-action="object-select" data-value="${o.id}" d="${o.path}"/>`).join('')}</svg>${state.overlays?`<span class="mask-label">${REVIEW.objects.find(o=>o.id===state.selectedObject).label}</span>`:''}</div><div class="photo-caption"><span>Illustrative vector outlines · not model output</span><span>Original photo preserved</span></div></div><aside class="object-aside"><div class="panel-head"><div><h2>Components</h2><p class="small">4 object groups</p></div><span class="small muted">Count</span></div><div class="object-list">${REVIEW.objects.map(o=>`<div class="object-row ${state.selectedObject===o.id?'selected':''} ${state.removed.has(o.id)?'removed':''}"><button class="object-select" data-action="object-select" data-value="${o.id}" aria-pressed="${state.selectedObject===o.id}"><b>${o.label}</b><strong class="num">${o.count}</strong></button><p>${o.material} · model score ${o.score}</p><div class="decisions">${btn(state.removed.has(o.id)?'Restore':'Keep','object-keep',o.id,'small '+(!state.removed.has(o.id)?'primary':''),state.removed.has(o.id)?'':'check')}${btn('Remove','object-remove',o.id,'quiet small')}</div></div>`).join('')}</div><div class="object-footer"><p class="small">${4-state.removed.size} of 4 groups kept<br>Edits are local to this preview.</p>${btn('Flag missing object','missing-object','','small')}</div></aside></div><div class="actionbar"><div><strong class="small">A focused view of the photo.</strong><p>Selection carries the emphasis. Outlines can be hidden at any time.</p></div><div class="row">${btn(state.photoReviewed?'Photo reviewed':'Mark photo reviewed','photo-reviewed','','primary','check')}</div></div><p class="footnote">Per-photo records, mask fields, tap-to-add, and new-object corrections remain backend design work. No segmentation model runs in this concept.</p>`}
function assetTable(completed=false){return `<div class="panel tablewrap"><table><thead><tr><th>Component</th><th>Recovery period</th><th>Quantity</th><th>Unit cost</th><th>Total cost</th><th>Review</th><th></th></tr></thead><tbody>${REVIEW.assetRows.map((a,i)=>`<tr><td><b>${a[0]}</b><p class="small">${a[1]}</p></td><td><span class="badge">${a[2]}</span></td><td class="num">${a[3]} <span class="muted">${a[4]}</span></td><td class="num">${a[5]}</td><td class="num strong">${a[6]}</td><td><span class="badge ${completed||a[7]==='Reviewed'?'complete':'review'}">${completed?'Reviewed':a[7]}</span></td><td><a class="button small" href="#asset-detail" data-select-asset="${i}">Review ${icon('chevron',12)}</a></td></tr>`).join('')}</tbody></table></div>`}
function assets(){return `${steps(3)}${heading('Review assets','Check each component’s classification, quantity and cost against its source.',goButton('Review one at a time','asset-detail',true))}<div class="metrics"><div class="metric"><p>Components</p><div class="value">4</div><span class="small">Visible sample rows</span></div><div class="metric"><p>Reviewed</p><div class="value">2</div><span class="small">Of 4 sample rows</span></div><div class="metric"><p>Needs review</p><div class="value">2</div><span class="small">Engineer decision required</span></div><div class="metric"><p>Illustrative total cost</p><div class="value">$875,768</div><span class="small">Not a property valuation</span></div></div>${assetTable()}<div class="note" style="margin-top:22px"><h3>Classification stays an engineering decision.</h3><p>Recovery periods and costs shown here are illustrative. Confirm each component against the applicable study evidence.</p></div><div class="actionbar"><p>Evidence must exist before the UI presents it as verified.</p><div class="row">${btn('Request corrections','request-corrections','assets_review')}${btn('Approve assets','approve','assets_review','primary','check')}</div></div>`}
function assetDetail(verification=false){const a=REVIEW.assetRows[state.selectedAsset],tab=state.assetTab;return `${steps(3)}${heading(verification?'Verify asset':a[0],verification?'Check the component details and supporting source before marking it reviewed.':`Harbor House / ${a[1]} / Sample component`,goButton('All assets','assets',false,'back'))}<div class="asset-layout"><nav class="asset-nav" aria-label="Assets">${REVIEW.assetRows.map((a,i)=>`<a class="${i===state.selectedAsset?'active':''}" href="#asset-detail" data-select-asset="${i}">${a[0]}<span class="small">${i>1?'✓':'○'}</span></a>`).join('')}</nav><section class="asset-main"><div class="row between"><span class="badge review">Needs review</span><span class="small muted">Draft · sample only</span></div><div class="tabs" style="margin-top:12px">${['Overview','Quantity','Classification','Costs','Documentation'].map(t=>`<button class="${tab===t?'active':''}" data-action="asset-tab" data-value="${t}">${t}</button>`).join('')}</div><div style="padding-top:22px">${tab==='Overview'?`<h2>${a[0]}</h2><p style="font-size:12px;margin-top:10px">Review the quantity, classification, cost basis, and source documentation before accepting this component.</p><div class="line-item"><span class="muted">Quantity</span><strong>${a[3]} ${a[4]}</strong></div><div class="line-item"><span class="muted">Suggested period</span><strong>${a[2]}</strong></div><div class="line-item"><span class="muted">Cost per unit</span><strong>${a[5]}</strong></div><div class="line-item"><span class="muted">Total cost</span><strong>${a[6]}</strong></div><div class="note" style="margin-top:20px"><h3>Review the supporting source</h3><p>Keep the original photo or document alongside your quantity, classification and cost review.</p></div>`:tab==='Quantity'?`<h2>Quantity takeoff</h2><p class="small" style="margin:10px 0 20px">Compare the estimated quantity with source photos and drawings.</p><div class="form-grid"><div class="field"><label for="quantity">Quantity</label><input id="quantity" value="${a[3].replace(',','')}"></div><div class="field"><label for="unit">Unit</label><select id="unit"><option>${a[4]}</option><option>each</option><option>sq ft</option><option>linear ft</option></select></div></div><div class="note" style="margin-top:22px"><p>Sample estimate. Confirm the quantity against the source before accepting it.</p></div>`:tab==='Classification'?`<h2>Classification</h2><div class="line-item"><span>Suggested recovery period</span><strong>${a[2]}</strong></div><div class="line-item"><span>Evidence status</span><span class="badge review">Not connected</span></div><div class="field" style="margin-top:20px"><label for="classification-reason">Engineer’s rationale</label><textarea id="classification-reason" placeholder="Record the basis for your classification."></textarea></div><p class="footnote">Citation cards become available when the evidence endpoint returns real records. No fabricated IRS citation is shown.</p>`:tab==='Costs'?`<h2>Cost basis</h2><div class="line-item"><span>Quantity</span><strong>${a[3]} ${a[4]}</strong></div><div class="line-item"><span>Unit cost</span><strong>${a[5]}</strong></div><div class="line-item"><span>Extended cost</span><strong>${a[6]}</strong></div><div class="field" style="margin-top:20px"><label for="cost-source">Cost source</label><select id="cost-source"><option>Sample source · not verified</option></select></div><p class="footnote">Actual source edition, location adjustment, and retrieval date should be shown once supplied.</p>`:`<h2>Documentation</h2><div class="field" style="margin-top:20px"><label for="asset-notes">Engineer notes</label><textarea id="asset-notes" placeholder="Add supporting context for this component."></textarea></div><div class="file-row">${icon('file')}<div class="grow"><strong class="small">Appraisal · source association</strong><p class="small">Illustrative attachment</p></div><span class="badge">Sample</span></div>${btn('Preview document association','future','The working application’s document association flow will be retained.','small')}`}</div></section><aside class="reference-panel"><div><h3>Supporting evidence</h3><span class="badge review">Evidence not connected</span><p style="margin-top:15px">No classification evidence is available in this preview. Review the source photo while checking this component.</p><div class="line-item"><span>Source</span><span>Property photos</span></div><a class="screen-link" href="#viewer">Inspect source photo</a></div><img src="assets/${state.selectedAsset===2?'exterior':'kitchen'}.webp" alt="Illustrative source photo"></aside></div><div class="actionbar"><p>Keep draft edits separate from the gate decision.</p><div class="row">${btn('Save draft','save-study-draft')}${btn('Mark reviewed','asset-reviewed','','primary','check')}</div></div>`}
function complete(){return `${steps(4)}${heading('Study schedule','Review the completed allocation and its delivery status.',goButton('Review history','activity'))}<section class="panel"><div class="report-cover"><div><span class="badge complete">Completed · illustrative</span><h2>Harbor House</h2><p>Cost segregation schedule</p><p class="small" style="margin-top:10px">Revision 1 / October 16, 2026 / Sample engineering workspace</p></div><div>${logo()}<p class="small" style="margin-top:25px">Engineer review recorded<br>Illustrative state only</p></div></div><div class="panel-body"><div class="metrics"><div class="metric"><p>Total allocated cost</p><div class="value">$875,768</div></div><div class="metric"><p>5-year property</p><div class="value">$9,088</div></div><div class="metric"><p>7 & 15-year property</p><div class="value">$24,680</div></div><div class="metric"><p>39-year property</p><div class="value">$842,000</div></div></div>${assetTable(true)}<div class="actionbar"><p>Sample values reconcile. This is not a generated report.</p><div class="row">${btn('Preview export options','export','','primary','download')}</div></div></div></section><p class="footnote">Recovery periods are illustrative. Residential schedules may include 27.5-year property. Report generation, signatures, exports, and download receipts still need real services.</p>`}
function settings(){return `${heading('Settings','Manage the sources and preferences behind your workspace.')}<nav class="settings-nav" aria-label="Settings sections">${['Cost sources','Workspace'].map(t=>`<button data-action="setting" data-value="${t}" class="${state.setting===t?'active':''}">${t}</button>`).join('')}<a href="#team" style="padding:12px 0">Team & access</a></nav>${state.setting==='Cost sources'?`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Cost data sources</h2><span class="badge">Design concept</span></div><div class="panel-body"><p class="small">Upload your licensed cost data, then review its import status before it becomes available for studies.</p><div class="file-row" style="margin:14px 0 20px">${icon('file',22)}<div class="grow"><strong>Workspace cost database</strong><p class="small">No import service connected in this preview</p></div><span class="badge">Not connected</span></div>${btn('Preview import flow','future','Import should show validation, version, source, and processing state once backend ingestion exists.','','upload')}</div></section><aside class="note"><h3>Source details matter.</h3><p>Edition, date, location adjustments, and licensing should be visible alongside imported cost data. A selected file is not a successful import.</p></aside></div>`:`<section class="panel" style="max-width:760px"><div class="panel-head"><h2>${state.setting}</h2><span class="badge">Proposed</span></div><div class="panel-body"><div class="form-grid"><div class="field"><label for="setting-name">${state.setting==='Profile'?'Full name':'Workspace name'}</label><input id="setting-name" value="${state.setting==='Profile'?'Alex Morgan':'Enterprise workspace'}"></div><div class="field"><label for="setting-email">${state.setting==='Profile'?'Email':'Display timezone'}</label><input id="setting-email" value="${state.setting==='Profile'?'engineer@example.test':'America/Los_Angeles'}"></div></div><div class="actionbar"><p>Proposed settings UI; no account changes are made.</p>${btn('Preview save','future','This settings change is local design behavior only.','primary')}</div></div></section>`}`}
function team(){return `${heading('Team & access','A proposed workspace administration page. Roles and membership actions need their own services.',btn('Invite member','invite','','primary','plus'))}<div class="audit-banner">Proposed enterprise page. Existing API authorization includes organization roles, but this member-management UI is not connected.</div><section class="panel tablewrap"><table><thead><tr><th>Member</th><th>Workspace role</th><th>Access</th><th></th></tr></thead><tbody>${[['Alex Morgan','Engineer','Active'],['Jordan Lee','Owner','Active'],['Casey Park','Viewer','Invitation pending']].map((m,i)=>`<tr><td><div class="property"><span class="avatar">${m[0].split(' ').map(x=>x[0]).join('')}</span><div><b>${m[0]}</b><small>Sample member</small></div></div></td><td>${m[1]}</td><td><span class="badge ${i===2?'review':'complete'}">${m[2]}</span></td><td>${btn('Manage access','future','Role changes, invitation revocation, and removal need enforced backend permissions.','small')}</td></tr>`).join('')}</tbody></table></section><div class="note" style="margin-top:25px"><h3>Access should be explicit.</h3><p>Separate study review from workspace administration. Show permission-denied and expired-invitation states before introducing more authentication options.</p></div>`}
function activity(){return `${heading('Study activity','A proposed record of processing, corrections, and engineer decisions.',goButton('Open study','appraisal'))}<div class="audit-banner">Illustrative history. Workflow runs and latest reviews exist; a complete attributed event feed and revision diffs need backend support.</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Harbor House</h2><span class="badge">Revision 1</span></div><div class="panel-body timeline">${[['9:42 am','Appraisal ready for review','Extraction completed. Waiting for an engineer’s decision.'],['9:38 am','Photo analysis completed','48 photos processed in the sample study.'],['9:34 am','Processing started','Appraisal extraction and property photo analysis began.'],['9:32 am','Source documents registered','Appraisal and 48 photos added to the study.'],['9:30 am','Study created','Alex Morgan created Harbor House.']].map((e,i)=>`<div><span class="check">${i===0?'○':'✓'}</span><div><span class="muted small">October 16 · ${e[0]}</span><h3 style="margin-top:5px">${e[1]}</h3><p>${e[2]}</p></div></div>`).join('')}</div></section><aside class="panel panel-body" style="align-self:start"><h3>Decision history</h3><p class="small" style="margin-top:15px">No engineer decision has been recorded in this illustrative revision.</p><div class="line-item"><span>Active gate</span><strong>Appraisal review</strong></div><div class="line-item"><span>Waiting since</span><strong>9:42 am · sample</strong></div></aside></div>`}
function audit(){let a=REVIEW.audit.find(x=>x.id===state.audit)||REVIEW.audit[1];return `${heading('Existing pages & design findings','Source-grounded page audit, with visual baselines from an isolated fixture copy.')}<div class="audit-banner">All 15 page.tsx routes were inspected in source. Baselines show existing components with local sample data, system-font fallback, and disabled live services. They are not production end-to-end test evidence.</div><div class="audit-layout"><nav class="audit-nav" aria-label="Page audit">${REVIEW.audit.map(x=>`<button class="${x.id===a.id?'active':''}" data-action="audit-page" data-value="${x.id}">${x.title}</button>`).join('')}</nav><article class="audit-content"><h2>${a.title}</h2><p><strong class="strong">${a.route}</strong><br>${a.finding}</p><div class="row between wrap" style="margin-bottom:18px"><span class="small muted">${a.verified}</span>${goButton('Open proposed design',a.proposal,true)}</div>${a.baseline?`<div class="compare"><div><h3>Existing · isolated fixtures</h3><a href="baseline/${a.baseline}" target="_blank"><img class="baseline-image" src="baseline/${a.baseline}" alt="Existing ${a.title} screen rendered with isolated fixtures"></a></div><div><h3>Proposed · design concept</h3><a href="#${a.proposal}"><img class="baseline-image" src="proposed/${a.proposal}.jpg" alt="Proposed ${a.title} visual concept"></a></div></div>`:''}<div class="audit-facts"><section><h3>Keep</h3><ul>${a.keep.map(x=>`<li>${x}</li>`).join('')}</ul></section><section><h3>Improve</h3><ul>${a.change.map(x=>`<li>${x}</li>`).join('')}</ul></section></div><p class="footnote">Owning source: ${a.file}</p></article></div>`}
function roadmap(){return `${heading('Prepare for an enterprise service','A proposed page map. Design can move ahead; live controls follow verified backend support.')}<div class="panel panel-body" style="margin-bottom:28px"><h2>The existing identity, refined.</h2><p class="small" style="margin-top:10px">Preserve the existing Basis identity and landing-page structure. Use soft backgrounds, frosted navigation, and layered controls for depth, with solid surfaces for documents, tables, and evidence.</p><div class="swatches">${[['Basis green · existing','#669A80'],['Primary 700 · existing','#456d5a'],['Primary 800 · existing','#355047'],['Primary 50 · existing','#f0f7f4'],['Paper','#ffffff'],['Review amber','#875820']].map(([n,c])=>`<span class="swatch"><i style="background:${c}"></i>${n} ${c}</span>`).join('')}</div><p class="small">Existing Basis logo assets and the app’s primary palette are retained. Inter-style sans-serif typography with system fallbacks. Layered 10–18px surface corners, restrained translucent chrome, tabular numbers, compact tables, visible focus, and reduced-motion/transparency fallbacks.</p></div><h2>Pages to add or complete</h2><div class="roadmap-list">${REVIEW.roadmap.map(r=>`<section class="roadmap-item"><div><span class="badge ${r.priority.startsWith('Before')?'review':''}">${r.priority}</span><h3>${r.name}</h3></div><div><h3>Frontend preparation</h3><p>${r.ui}</p></div><div><h3>Backend dependency</h3><p>${r.backend}</p></div></section>`).join('')}</div><section style="margin-top:35px"><h2>Contract findings that affect the design</h2><div class="audit-facts"><div><h3>Verified in the current code</h3><ul><li>The workflow response wraps progress inside status; status can be null.</li><li>The Stage enum has extracting, appraisal_review, rooms_review, assets_processing, assets_review, exporting, and completed. There is no separate photo-analysis stage.</li><li>Photo analysis runs during extracting. pending_photos is remaining work; completed_photos includes terminal attempts. Flagged photos must remain visible.</li><li>Approve with corrections is rejected by the decision route. The OpenAPI example still contradicts that rule.</li><li>Decisions carry stage and revision and are accepted at the active gate.</li><li>Evidence is an empty-list stub in this checkout.</li><li>Cancellation uses execution/run state; StudyStatus has no cancelled member.</li></ul></div><div><h3>Still needs agreement</h3><ul><li>The checked OpenAPI file does not expose full appraisal, room-inventory, or asset review read models. Do not claim those three gate payloads are frozen.</li><li>Per-photo masks, object edits, and manual additions remain presentation models here.</li><li>Cancellation display must reconcile execution_status with run outcome, including a cooperatively completed cancellation.</li><li>Residential 27.5-year and nonresidential 39-year treatment must be driven by applicable study data.</li><li>A generated client is useful after schema agreement; the integration duration has not been estimated or verified.</li></ul></div></div></section><section style="margin-top:35px"><h2>Reference principles</h2><p class="small" style="margin-top:12px">Research reviewed October 16, 2026. These are design references, not endorsements or feature parity claims.</p><div class="audit-facts"><div><h3><a class="screen-link" href="https://cursor.com/" target="_blank" rel="noreferrer">Cursor</a></h3><p>Product-forward storytelling and restrained site navigation. Borrow the clarity and real interface imagery, not its exact branding.</p><h3 style="margin-top:18px"><a class="screen-link" href="https://linear.app/" target="_blank" rel="noreferrer">Linear</a></h3><p>Workflow-focused hierarchy and a consistent system of product surfaces.</p></div><div><h3><a class="screen-link" href="https://www.procore.com/estimating" target="_blank" rel="noreferrer">Procore Estimating</a></h3><p>Domain-relevant reference for keeping takeoff information tied to source material.</p><h3 style="margin-top:18px">Where Basis is different</h3><p>The engineer needs to review evidence, quantities, and classifications. The memorable element should be the photo-to-component interaction, surrounded by quiet, practical controls.</p></div></div></section>`}
function render(){const screens={study:()=>typeof archiveStudy==='function'?archiveStudy():'',library:()=>typeof studyLibrary==='function'?studyLibrary():'',files:()=>typeof studyFiles==='function'?studyFiles():'',landing,login,dashboard,upload,processing,appraisal,rooms,viewer,assets,'asset-detail':()=>assetDetail(false),verification:()=>assetDetail(true),complete,settings,team,activity,audit,roadmap,admin:()=>ownerAdmin(),join:()=>joinWorkspace()};if(!screens[state.screen])state.screen='landing';root.innerHTML=reviewbar()+(state.screen==='landing'||state.screen==='login'||state.screen==='join'?screens[state.screen]():shell(screens[state.screen]()));document.title=`Basis · ${REVIEW.screens.find(x=>x[0]===state.screen)?.[1]||'Design review'}`;}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>{t.style.display='none'},4500)}
function navigate(screen){location.hash=screen;if(state.screen===screen)render()}
function modal(title,body,actions){let previous=document.activeElement;const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${title}</h2>${body}<div class="actions">${actions}</div></section>`;root.append(backdrop);const close=()=>{backdrop.remove();previous?.focus()};backdrop.addEventListener('click',e=>{if(e.target===backdrop||e.target.closest('[data-close]'))close()});backdrop.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return}if(e.key==='Tab'){const els=[...backdrop.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});backdrop.querySelector('input,textarea,button')?.focus();return backdrop}
const closeBtn='<button class="button" data-close>Close</button>';
root.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}const proc=e.target.closest('[data-processing]');if(proc)state.processing=proc.dataset.processing;const asset=e.target.closest('[data-select-asset]');if(asset){state.selectedAsset=Number(asset.dataset.selectAsset);state.assetTab='Overview';if(state.screen==='asset-detail')render()}
const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,value=target.dataset.value;switch(action){case'filter':state.studyFilter=value;render();break;case'metrics':state.metrics=!state.metrics;render();break;case'sample-login':toast('This is a sign-in concept. Opening the sample workspace without authentication.');navigate('dashboard');break;case'demo':modal('Book a demo','<p>This retains the original landing page’s demo entry point. A contact form and scheduling destination still need to be connected. No message is sent from this preview.</p>',closeBtn);break;case'access':modal('Workspace access','<p>This page would explain how an invited engineer joins a workspace and how to request access. The production invitation service is not connected.</p>',closeBtn);break;case'preview-analysis':if(!state.propertyName.trim()){toast('Enter a property name to preview the study.');document.getElementById('property-name').focus();return}state.processing='processing';navigate('processing');break;case'cancel':{const m=modal('Cancel this sample study?','<p>This demonstrates the confirmation state. It does not cancel a workflow or delete any documents.</p>',`${closeBtn}<button class="button danger" id="confirm-cancel">Preview cancelled state</button>`);m.querySelector('#confirm-cancel').onclick=()=>{m.remove();state.processing='cancelled';render();toast('Showing the cancelled design state.')};break}case'select-field':state.appraisal=Number(value);render();break;case'verify-field':state.verifiedFields.add(Number(value));state.appraisal=Math.min(Number(value)+1,REVIEW.appraisalFields.length-1);render();break;case'correct-field':{const i=Number(value),f=REVIEW.appraisalFields[i];const m=modal('Correct '+f.label,`<p>Changing a value requires requesting corrections. The workflow will re-extract the appraisal.</p><div class="field"><label for="correction-value">Correct value</label><input id="correction-value" value="${esc(state.corrections[i]||f.value)}"></div><div class="field" style="margin-top:15px"><label for="correction-reason">Reason</label><textarea id="correction-reason" placeholder="Explain the source of the correction."></textarea></div>`,`${closeBtn}<button class="button primary" id="save-correction">Add correction</button>`);m.querySelector('#save-correction').onclick=()=>{const v=m.querySelector('#correction-value').value.trim(),r=m.querySelector('#correction-reason').value.trim();if(!v||!r){toast('Enter a value and a reason.');return}state.corrections[i]=v;m.remove();render();toast('Correction added locally. Use Request corrections to return this stage.')};break}case'request-corrections':{const m=modal('Request corrections',`<p>The production decision will be reject for <strong>${esc(value)}</strong> at the active revision. Nothing is submitted in this preview.</p><div class="field"><label for="review-comment">Correction instructions</label><textarea id="review-comment" placeholder="Describe what needs to be corrected."></textarea></div>`,`${closeBtn}<button class="button primary" id="send-correction">Preview return for correction</button>`);m.querySelector('#send-correction').onclick=()=>{if(!m.querySelector('#review-comment').value.trim()&& !Object.keys(state.corrections).length){toast('Add correction instructions first.');return}m.remove();toast('Local preview: return for correction. No decision was sent.');state.processing='extracting';navigate('processing')};break}case'approve':if(value==='appraisal_review'&&Object.keys(state.corrections).length){toast('Corrections cannot be approved. Use Request corrections.');return}{const m=modal('Approve this review?',`<p>This previews approval of <strong>${esc(value)}</strong>, revision 1. The real UI must verify the active gate, revision, permissions, and required review work before submitting.</p>`,`${closeBtn}<button class="button primary" id="confirm-approval">Preview approval</button>`);m.querySelector('#confirm-approval').onclick=()=>{m.remove();state.approved.add(value);navigate(value==='appraisal_review'?'rooms':value==='rooms_review'?'assets':'complete');toast('Sample next stage shown. No approval was recorded.')};break}case'rooms-filter':state.roomsFilter=value;render();break;case'open-photo':openPhotoReview(Number(value));break;case'add-room':modal('Add a room','<p>The existing room creation and naming interaction will be retained. This concept uses local sample groups.</p>',closeBtn);break;case'object-select':state.selectedObject=value;render();break;case'object-keep':state.removed.delete(value);render();toast('Kept in the local sample inventory.');break;case'object-remove':state.removed.add(value);render();toast('Removed from the local sample inventory. Restore is available.');break;case'toggle-overlay':state.overlays=!state.overlays;render();break;case'missing-object':modal('Flag a missing object','<p>The viewer should leave room for a missing-object note. Tap-to-add, box selection, and creation of new object records require a finalized API. This preview does not pretend to perform detection.</p>',closeBtn);break;case'photo-reviewed':state.photoReviewed=true;render();toast('Photo marked reviewed in this preview only.');break;case'asset-tab':state.assetTab=value;render();break;case'asset-reviewed':toast('Component marked reviewed in this local concept. Gate approval remains a separate action.');break;case'setting':state.setting=value;render();break;case'audit-page':state.audit=value;render();break;case'future':toast(value);break;case'invite':modal('Invite a member','<p>Proposed invitation flow: enter a work email, choose an enforced role, and send an expiring invitation. No invitation is sent from this design review.</p>',closeBtn);break;case'export':modal('Export the schedule','<p>A delivery panel should show report format, revision, generation status, and a real download link.</p><div class="note"><h3>Export service not connected</h3><p>No PDF or spreadsheet was generated. The checked OpenAPI file has no report-download endpoint.</p></div>',closeBtn);break;}});
root.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
root.addEventListener('change',e=>{if(e.target.id==='screen-select')navigate(e.target.value);if(e.target.id==='workflow-state'){state.processing=e.target.value;render()}if(e.target.matches('.photo-group')){state.group[e.target.dataset.photo]=e.target.value;toast('Photo moved to '+e.target.value+' in the local preview.')}if(e.target.id==='appraisal-file'){const file=e.target.files?.[0];if(file){if(!file.name.toLowerCase().endsWith('.pdf')){toast('Choose a PDF appraisal.');e.target.value='';return}state.uploads=[file.name];render();toast('File name selected locally. No upload took place.')}}});
root.addEventListener('input',e=>{if(e.target.id==='property-name')state.propertyName=e.target.value;if(e.target.id==='client-name')state.clientName=e.target.value;if(e.target.id==='property-address')state.propertyAddress=e.target.value;if(e.target.id==='study-search'){state.query=e.target.value;let rows=REVIEW.studies.filter(s=>(state.studyFilter==='All studies'||(state.studyFilter==='Needs review'&&['waiting_review','stalled'].includes(s.status))||(state.studyFilter==='Processing'&&s.status==='processing')||(state.studyFilter==='Completed'&&s.status==='completed'))&&s.property_name.toLowerCase().includes(state.query.toLowerCase()));document.getElementById('study-table').innerHTML=studyTable(rows)}});
window.addEventListener('hashchange',e=>{const next=location.hash.slice(1)||'landing';if(typeof guardStudyHashChange==='function'&&guardStudyHashChange(next,e))return;state.screen=next;render();window.scrollTo(0,0)});

